/**
 * Track catalog: every track needs a known BPM.
 * Demo loops are generated by `node scripts/gen-demo-tracks.mjs`.
 * To add real music: drop an mp3/m4a in assets/music and add a row with its BPM
 * (get BPM from the artist, a tagger app, or the backend).
 */
export type Track = { id: string; title: string; bpm: number; source: number };

export const TRACKS: Track[] = [
  { id: "loop120", title: "Demo Loop 120", bpm: 120, source: require("../../assets/music/loop_120.wav") },
  { id: "loop140", title: "Demo Loop 140", bpm: 140, source: require("../../assets/music/loop_140.wav") },
  { id: "loop160", title: "Demo Loop 160", bpm: 160, source: require("../../assets/music/loop_160.wav") },
  { id: "loop175", title: "Demo Loop 175", bpm: 175, source: require("../../assets/music/loop_175.wav") },
];

/** Keep time-stretch subtle; beyond this, switch tracks instead. */
export const MAX_STRETCH = 0.12;

/** Track whose native BPM is closest to target (ratio-wise). */
export function bestTrackFor(bpm: number, tracks = TRACKS): Track {
  return tracks.reduce((best, t) => (Math.abs(Math.log(bpm / t.bpm)) < Math.abs(Math.log(bpm / best.bpm)) ? t : best));
}
